add('Advanced network surfaces with independent edge continuity','CSNetworkSurfaceAdvanced collects U/V curves, translates four continuity-mode selectors, calls NurbsSurface.CreateNetworkSurface with .001 edge tolerance, .01 interior tolerance and application angle tolerance, converts through BRep/OnBrep and reports mapped error codes.',[E('CSBlocks.Surfaces/CSNetworkSurfaceAdvanced.cs','NurbsSurface.CreateNetworkSurface','CSNetworkSurfaceAdvanced.Update')],K.concat(['NetworkSurfaceHelper continuity/error mapping']),'local-kernel-required',['Create a U/V network with independent start/end continuity and compare positional/tangent/curvature seams against PC.','Use incompatible networks to compare error strings and invalid-mode behavior; repeat at small jewelry dimensions.']);
add('Surface offset and standard extrusion/sphere/planar surfaces','CSSurfaceOffset flattens input, offsets each ICSSurface at requested distance using application tolerance, wraps results and emits scalar for one or array otherwise. Other surface/extrusion/sphere identities are catalogued separately.',[E('CSBlocks.Surfaces/CSSurfaceOffset.cs','iCSSurface.GetSurface().Offset','CSSurfaceOffset.Update')],K,'local-kernel-required',['Offset a trimmed/curved surface inward and outward and compare boundaries and normals.','Offset an array of mixed surface/non-surface data; compare output filtering and scalar/array convention.'],['Only offset body is audited in this grouping; extrusion/sphere/planar variants need fixture validation.']);
add('BRep booleans, join, split and capping semantics','CSBooleanDifference supports a flip input that actually selects intersection, calls kernel booleans at .01 tolerance and returns duplicated left input if result is null or empty. CSBooleanUnion uses application tolerance and also falls back to duplicated input. Failed operations can therefore look like successful unchanged geometry.',[E('CSBlocks.Solids/CSBooleanDifference.cs','Brep[] array = (value ?','CSBooleanDifference.Update'),E('CSBlocks.Solids/CSBooleanUnion.cs','Brep[] array = Brep.CreateBooleanUnion','CSBooleanUnion.Update')],K.concat(['CSUtilDataHelper clean BRep filtering']),'local-kernel-required',['Boolean overlapping, tangent and disjoint jewelry solids; compare output count and unchanged-input fallback at .01 versus application tolerance.','Set difference flip=true and verify intersection result; test split/join/cap registered node fixtures separately.'],['Mesh boolean, split/join/cap bodies are indexed but not individually behavior-verified.']);
add('Rigid transforms, object-local transforms, mirrors and polar arrays','CSMirror resolves optional coordinate transform/inverse, scales selected axes negatively, duplicates combinations when requested and flips geometry orientation after handedness changes. CSPolarArray duplicates objects in nested primary/sub loops with selected axes, offsets and optional visible-count clipping.',[E('CSBlocks.Transforms/CSMirror.cs','public override bool Update()','CSMirror.Update'),E('CSBlocks.Transforms/CSMirror.cs','CSUtilMath.IsFlipTransform','CSMirror.Update'),E('CSBlocks.Transforms/CSPolarArray.cs','for (int i = 0; i < value; i++)','CSPolarArray.Update')],K.concat(['CSData transform/flip preservation','world versus object frame']),'local-transform-core-required',['Mirror asymmetric solid on X/Y/Z with duplicate on/off and custom frame; compare combinations, normals and source preservation.','Build primary/sub polar array with nondefault axes/count visibility and compare transform order, object count and ordering.'],['38 current and 12 obsolete transform registrations must retain distinct numeric/frame semantics.']);
add('Flow along surface morph','CSFlowAlongSurface accepts surface or first BRep face, optionally transposes/reverses source UV, configures special planar source frame/lines, duplicates object data, morphs with tolerance .05 and flips output if FlipZ selected.',[E('CSBlocks.UDT/CSFlowAlongSurface.cs','public override bool Update()','CSFlowAlongSurface.Update'),E('CSBlocks.UDT/CSFlowAlongSurface.cs','cSFlowAlongSurfaceMorph.Tolerance = 0.05','CSFlowAlongSurface.Update')],K.concat(['CSFlowAlongSurfaceMorph','UV parameterization']),'local-nonlinear-morph-required',['Flow asymmetric planar motif to doubly curved target with every UV swap/reversal and FlipZ; compare orientation and surface fidelity.','Use trimmed BRep sources/destinations and verify first-face selection and source data immutability.']);
add('Curved XY taper, ring pull and grouped deformation','CSCurvedTaperXY computes a bounding box and builds a three-position independent X/Y morph, clamping additional Z bounds to nonnegative, duplicates input and morphs at .05. CSPullToRail derives local unscaled frame and top-center angle, gets oriented bounds and morphs duplicated data, emitting only successful results.',[E('CSBlocks.UDT/CSCurvedTaperXY.cs','CSCurvedTaperXYMorph cSCurvedTaperXYMorph','CSCurvedTaperXY.Update'),E('CSBlocks.UDT/CSPullToRail.cs','PullToRailMorph spaceMorph = new PullToRailMorph','CSPullToRail.Update')],K.concat(['SpaceMorph/OnSpaceMorph','PullToRailMorph','group-center variants']),'local-nonlinear-morph-required',['Apply unequal X/Y taper at three Z stations to mesh, BRep and gem group; compare section bounds and unchanged source data.','Pull to ring with rotated/scaled objects, vary multiplier and center-control/group modes using per-GUID fixtures.'],['PullToCurve/PlopOnRingRail/RingTaper/group variants are indexed; individual bodies not all inspected.']);
add('Dimensional measurement: curve length and directional surface distance','CSCurveLength emits per-curve kernel length and scalar/array shape. CSDistanceFromSurface extracts object transform origin/Z direction, intersects a +/-100 line against BRep at application tolerance, then selects closest overlap/intersection point. It is directional distance, not arbitrary Euclidean closest distance.',[E('CSBlocks.Curves/CSCurveLength.cs','double length = value.GetLength()','CSCurveLength.Update'),E('CSBlocks.Core/CSDistanceFromSurface.cs','Intersection.CurveBrep','CSDistanceFromSurface.Update')],K,'local-kernel-measurement-required',['Measure circle/arc/spline lengths and compare to PC under model units/tolerance.','Use a surface whose nearest point is off object Z axis and verify directional intersection result; include overlap and no-hit cases.'],['Other point/curve/rail/planar distance nodes are inventoried with separate acceptance fixtures.']);
add('Volume centroid and approximate union volume','CSVolumeCentroid collects solid BReps, caps open BReps when possible and accepts closed meshes, computes VolumeMassProperties and emits a centroid. The recovered code indexes list3[0] without a guard and then sums every entry including that first item again. MeshRepairHelper converts meshes to GMesh and OctTree.GetVolume computes voxel union at depth 11 with pixel-count correction and scale correction.',[E('CSBlocks.Bails/CSVolumeCentroid.cs','VolumeMassProperties volumeMassProperties = list3[0]','CSVolumeCentroid.Update'),E('CS.Utilities.Helpers/MeshRepairHelper.cs','public static double GetVolumeViaOctTree','MeshRepairHelper.GetVolumeViaOctTree'),E('OctTree/OctTree.cs','DoTreeInternal(lstMesh, 11','OctTree.GetVolume')],K.concat(['OctTree/GMesh/OctShell','closed-shell policies']),'local-kernel-and-voxel-volume-required',['Measure two asymmetric solids of known differing volumes and centers; capture PC centroid including first-entry weighting behavior.','Run only-open/unclosable input and document error; compute two overlapping spheres with octree volume and compare PC within calibrated voxel tolerance.'],['Observed centroid edge cases may be recovered-source defects. Approximate octree volume must not be replaced by naive sum of overlapping mesh volumes.']);
add('Text, font outlines and solid lettering','CSTextObjects resolves font enum description in Rhino font table, explodes TextEntity to outlines, makes planar BReps, offsets first faces by half depth on both sides into solids, fixes orientation and optionally translates union bounding-box center to origin.',[E('CSBlocks.Tools/CSTextObjects.cs','RhinoDoc.ActiveDoc.Fonts.FindOrCreate','CSTextObjects.Update'),E('CSBlocks.Tools/CSTextObjects.cs','Brep.CreateFromOffsetFace','CSTextObjects.Update')],K.concat(['font enum/name mapping','installed font faces and metrics']),'local-font-outline-equivalence-required',['Generate bold/italic text containing holes and non-ASCII characters; compare outline nesting, depth and solid closure with identical PC font.','Center and uncenter same text and compare world bounds, glyph spacing and output count.'],['iPad font availability and glyph metric equivalence unverified; user font files may be external dependencies.']);
add('Captured Rhino geometry and file-backed part groups','CSRhinoObjectsFromBoundingBox binary Read loads embedded 3dm objects and sets _useObjects; otherwise Update captures selected Rhino objects inside an expanded XY box spanning +/-1000 Z and stores name/layer user strings. Write embeds 3dm geometry. CSGroupOfRhinoObjectsFilePath chooses allowed gem orientations, normalizes geometry to gem dimensions and attaches CSMounting tags.',[E('CSBlocks.Core/CSRhinoObjectsFromBoundingBox.cs','public override bool Read(ref OnBinaryArchive archive','CSRhinoObjectsFromBoundingBox.Read'),E('CSBlocks.Core/CSRhinoObjectsFromBoundingBox.cs','RhinoDoc.ActiveDoc.Objects.GetSelectedObjects','CSRhinoObjectsFromBoundingBox.Update'),E('CSBlocks.Core/CSRhinoObjectsFromBoundingBox.cs','archive.BeginWrite3dmChunk(268435475u','CSRhinoObjectsFromBoundingBox.Write'),E('CSBlocks.Core/CSGroupOfRhinoObjectsFilePath.cs','public override bool Update()','CSGroupOfRhinoObjectsFilePath.Update')],K.concat(['embedded 3dm object payloads','external file paths/parts/previews','CSName/CSLayer/CSMounting tags']),'local-geometry-and-path-remapping-required',['Load PC fixture with captured geometry but no original source file; ensure geometry survives and can regenerate.','Import part group with allowed gem-shape list and CSMounting tags; compare normalization, disabled choices, previews and material assignment.','Round-trip this node through proposed JSON interchange and verify _objects are retained; own JSON overrides are absent in recovered class.'],['Concrete JSON/binary asymmetry: inherited JSON alone may omit custom captured geometry. Full read/write field analysis belongs to primary audit.']);
add('SMI manufacturing profile tools and textual output','SMI cutter nodes operate on profile curves and transform metadata; CSSMICutterComfortFit passes profile, transform and edge height into CutterComfortFit. CSSMIOutput walks numeric/profile inputs and builds text sections using the block identifier and profile names. Shell, interval and cutter variants form a manufacturing-specific family beyond visual geometry.',[E('CSBlocks.SMI/CSSMICutterComfortFit.cs','CSUtilSMI.CutterComfortFit','CSSMICutterComfortFit.Update'),E('CSBlocks.SMI/CSSMIOutput.cs','public override bool Update()','CSSMIOutput.Update')],K.concat(['CSUtilSMI manufacturing curves','locale numeric formatting/profile names']),'local-kernel-and-manufacturing-output-required',['Apply comfort-fit cutter to a transformed profile at two edge heights; compare profile section and transform metadata.','Generate SMI output for numeric arrays and named profiles under PC locale and compare exact text lines; run all SMI cutter fixture IDs.'],['23 current/3 obsolete SMI registrations are inventoried; manufacturing controller/file contract not independently recovered in this scope.']);
add('Graph arithmetic, nonlinear controls and branching/array shape','CSNonlinear clamps numeric input, scales/translates a response curve into input/output ranges and intersects it at requested X. CSIfElse passes the selected branch data directly. This family also contains arithmetic/comparison/boolean reducers and array flatten/unarray/reorder utilities that influence builder topology and data shape.',[E('CSBlocks.Maths/CSNonlinear.cs','public override bool Update()','CSNonlinear.Update'),E('CSBlocks.Utilities/CSIfElse.cs','OutOutput.SetData(value ?','CSIfElse.Update')],K.concat(['graph data aliasing','channel flatten/scalar/array conventions']),'port-managed-core-plus-response-curves',['Evaluate nonlinear control below/inside/above range with increasing/decreasing response curves and compare output/branch geometry.','Toggle IfElse between scalar and nested arrays and compare aliasing/change propagation; validate arithmetic divide/NaN and boolean reducer edge cases per fixture.'],['Individual arithmetic/array implementations are declaration-inventoried; generic names alone do not establish exact edge semantics.']);
add('Display mesh preprocessing is distinct from manufacturing mesh','CSGenerateMesh duplicates flattened data and calls PreProcessDisplayInfo on CSOnGeometryData, then selects null/scalar/array output. It does not directly export an STL or invoke repair; display tessellation caches and manufacturing meshes follow separate paths.',[E('CSBlocks.Core/CSGenerateMesh.cs','cSOnGeometryData.PreProcessDisplayInfo()','CSGenerateMesh.Update')],K.concat(['CSOnGeometryData display meshing/cache']),'local-tessellation-and-cache-required',['Regenerate display mesh for trimmed curved BRep, then change a parameter and verify mesh invalidation and unchanged source.','Compare view quality and exported STL quality independently, including scalar/empty/multiple inputs.']);
add('Manufacturing mesh repair and native union','MeshRepairHelper caps and joins BReps at .001, converts geometry to triangular meshes, flips inward solid orientation, optionally prerepairs open shells, appends meshes and calls Netfabb repair. NetfabbRepairMesh scales input by 3, requires valid repaired result, scales back and unwelds at 22.5 degrees. NetfabbHelper dynamically loads Windows helper/managed DLLs and marshals pinned vertex/index buffers to native build-mesh.',[E('CS.Utilities.Helpers/MeshRepairHelper.cs','public static Mesh RepairMesh(List<GeometryBase> geometryBases, bool doExtendedRepair, bool doPreRepairShells, MeshingParameters','MeshRepairHelper.RepairMesh'),E('CS.Utilities.Helpers/MeshRepairHelper.cs','private static Mesh NetfabbRepairMesh','MeshRepairHelper.NetfabbRepairMesh'),E('CS.Utilities.Helpers/NetfabbHelper.cs','LibraryName = Path.Combine','NetfabbHelper static initializer'),E('CS.Utilities.Helpers/NetfabbHelper.cs','netfabbManagedBuildMesh(netfabbContext','NetfabbHelper.NetfabbBuildMesh')],['Rhino meshing and BRep topology','gemvision_helper64.dll','gemvision_netfabbmanaged.dll','native Netfabb engine/context','CSMeshRepairPath assets'],'major-native-platform-replacement-required',['Repair intersecting/open/reversed/disconnected jewelry meshes and compare watertightness, manifold edges, shell count and volume with PC normal/extended/prerepair options.','Verify thin prongs and milgrain survive tessellation and repair; measure dimensional drift after 3x scale round trip.'],['Native implementation and distributable iPad equivalent not established. RepairHelper and older Travis MeshRepair are both present and must be traced by actual call path.']);
add('Binary STL writer and optional repair export','RhinoServices.ExportDesignAsSTL sets center/side/accent gem flags and export mode, adds model to Rhino, calls Travis MeshRepair.CreateSTLFromRhinoObjects and cleans temporary document geometry. Binary writer triangulates, writes an 80-byte header, declared face count, normal/three vertices and zero attribute bytes. NaN vertex triangles are skipped after count is written, so malformed-count cases require tests.',[E('CounterSketchServer/RhinoServices.cs','public bool ExportDesignAsSTL','RhinoServices.ExportDesignAsSTL'),E('CS.Utilities.Travis/MeshRepair.cs','public static void CreateSTLFromRhinoObjects','MeshRepair.CreateSTLFromRhinoObjects'),E('CS.Utilities.Helpers/MeshRepairHelper.cs','public static bool SaveStlBinary','MeshRepairHelper.SaveStlBinary')],['Rhino temporary document/layers','CSOptionsExport gem-print flags','Travis MeshRepair','filesystem binary output'],'offline-local-export-after-kernel-replacement',['Export with all 8 center/side/accent inclusion combinations and repair on/off; verify triangle count, shell content, units and topology.','Validate each binary STL length equals 84+50*declaredFaces; include NaN/invalid geometry and assert explicit failure rather than silent corrupt output.'],['Service invokes Travis path; writer example in newer helper demonstrates format/edge behavior but caller path must be verified separately.']);
add('3DM export retaining user data and original BRep geometry','ExportDesignAs3DM disables mesh-object meshing, forces those blocks to regenerate, honors gem printing flags, adds model to Rhino and writes a temporary file with user data enabled, render meshes/bitmap table disabled and all objects selected. It copies to requested destination and deletes temporary model. It is geometry export, not full parametric project serialization.',[E('CounterSketchServer/RhinoServices.cs','public bool ExportDesignAs3DM','RhinoServices.ExportDesignAs3DM'),E('CounterSketchServer/RhinoServices.cs','WriteUserData = true','RhinoServices.ExportDesignAs3DM'),E('CounterSketchServer/RhinoServices.cs','RhinoDoc.ActiveDoc.WriteFile(tempPath','RhinoServices.ExportDesignAs3DM')],['Rhino 3dm writer/native geometry','FileWriteOptions','material/layer/user-string mapping','local filesystem'],'local-3dm-writer-equivalence-required',['Export editable BReps/curves/gems/mesh objects and reopen in PC Rhino; compare layer/material names, user strings and shape without render meshes.','Include/exclude gem categories and verify mesh-object regeneration yields intended analytic geometry and no temporary document objects remain.'],['Requires portable 3dm writer plus equivalent geometry/user-data representation; does not preserve graph by itself.']);
add('Photoreal rendering with material, environment and prop libraries','RenderHelper.GenerateCustomRender explicitly selects V-Ray, loads fullenv.visopt and selected environment .visopt, registers resource paths, controls batch/output/progress, inserts render objects and .3dm props/ground plane, loads .vismat materials and manages alpha contribution. It depends on renderer-specific scene/material APIs and local asset paths.',[E('CounterSketchServer.Utilities.Helpers/RenderHelper.cs','public static void GenerateCustomRender','RenderHelper.GenerateCustomRender'),E('CounterSketchServer.Utilities.Helpers/RenderHelper.cs','LoadVrayMaterials("fullenv.visopt")','RenderHelper.GenerateCustomRender'),E('CounterSketchServer.Utilities.Helpers/RenderHelper.cs','VRayInterface.LoadVisopt(text)','RenderHelper.GenerateCustomRender'),E('CounterSketchServer.Utilities.Helpers/RenderHelper.cs','VRayInterface.LoadVismat(text3)','RenderHelper.GenerateCustomRender')],['V-Ray Rhino plugin/VRayInterface','RMA/Rhino render document','RenderMaterials .visopt/.vismat/textures','Props .3dm and camera/groundplane state'],'major-renderer-and-asset-port-required',['Render same PC scene with gemstone/metal/skin materials, chosen environment and prop at fixed camera/resolution; compare image appearance and transparent alpha.','Work offline with complete bundled textures/environments/props; verify missing assets are explicit and output PNG saves locally.'],['Equivalent iPad rendering and legal availability of renderer/material assets are not established by source recovery.']);
add('Printer connection, support generation, job packing and controls','ProjetHelper connects by IP through Geomagic printer APIs, requires idle state to create supports, applies preview rotations, prepares model/supports and sends print jobs. Multiple-job printing validates FTX gray/green cartridge, rotates/packs meshes into boundary rectangle, generates native build file and sends it; abort/pause/resume/status APIs are exposed.',[E('CounterSketchServer.Utilities.Helpers/ProjetHelper.cs','public bool ConnectToPrinter','ProjetHelper.ConnectToPrinter'),E('CounterSketchServer.Utilities.Helpers/ProjetHelper.cs','public bool CSCreateSupportsForCSItem','ProjetHelper.CSCreateSupportsForCSItem'),E('CounterSketchServer.Utilities.Helpers/ProjetHelper.cs','public bool PrintCSModel','ProjetHelper.PrintCSModel'),E('CounterSketchServer.Utilities.Helpers/ProjetHelper.cs','public bool PrintMultipleJobs','ProjetHelper.PrintMultipleJobs')],['Geomagic.Print.Headless native printer SDK','printer on local network','device material/status APIs','support generation/build format','Rhino viewport conduit'],'external-device-integration-and-native-replacement',['Against a controlled supported printer or SDK simulator, test idle/busy/offline transitions, supports, model preview transforms, pause/resume/abort and error strings.','Pack multiple jobs near build bounds with both supported cartridge IDs and unsupported material; compare build file and explicit oversized-job rejection.'],['This feature inherently requires a physical/network device; an airplane-mode requirement cannot include sending printer jobs. No printer contacted in audit.']);
add('CAD commands: parallel-processing toggle and VR service start/stop','CSToggleBlockParallelProcessing is a hidden Rhino command that flips application state and forces graph redraw. CSVRStart/CSVRStop are MRhinoTestCommand wrappers returning success/failure around CSVRHelper server start/stop. These are the only three command-derived declarations found in the baseline.',[E('CounterSketchServer.Commands/CSToggleBlockParallelProcessing.cs','protected override Result RunCommand','CSToggleBlockParallelProcessing.RunCommand'),E('CounterSketchServer.Commands/CSVRStartCommand.cs','public override IRhinoCommand.result RunCommand','CSVRStartCommand.RunCommand'),E('CounterSketchServer.Commands/CSVRStopCommand.cs','public override IRhinoCommand.result RunCommand','CSVRStopCommand.RunCommand')],['Rhino command dispatch','CSVRHelper service/runtime','parallel scheduler'],'adapt-command-ui-and-optional-service',['Toggle processing twice and compare geometry ordering/cancellation/graph redraw against PC.','Start/stop VR service with already-running/failure states and verify reported command result; determine whether iPad product retains VR scope.'],['Absence of more command classes does not mean absence of callable service/UI operations; RhinoServices has broader entry points.']);

add('Legacy surface punching around gem rails','CSSurfacePunch1 combines channel spacings, computes left/right gem rails at positive and negative split distances, extends endpoints, closes open borders, lofts a splitter and invokes RhinoBrepSplit. Its Tests namespace does not remove its registered geometry behavior from old project dependencies.',[E('CSBlocks.Tests.Obsolete/CSSurfacePunch1.cs','public override bool Update()','CSSurfacePunch1.Update'),E('CSBlocks.Tests.Obsolete/CSSurfacePunch1.cs','RhUtil.RhinoBrepSplit','CSSurfacePunch1.Update')],K,'retain-versioned-local-algorithms',['Load SurfacePunch V1 PC fixture with open/closed gem row; compare punched BRep pieces and splitter selection.','Vary separate start/end spacing and split distance; compare endpoint rail extension and border closure.'],['Other SurfacePunch generations remain per-GUID fixture requirements.']);
const legacyBodyObservations=[];
function legacy(id,file,needle,behavior,test){
 const f=features.find(f=>f.id===id);if(!f)throw Error('Bad legacy feature group');
 const p=rel(path.join(base,...file.split('/')));const t=types.find(t=>t.path===p&&t.registeredBlock)||types.find(t=>t.path===p);
 const ev=evidence(file,needle,t.qualifiedName+'.Update');f.evidence.push(ev);
 legacyBodyObservations.push({type:t.qualifiedName,capabilityId:id,observedBehavior:behavior,evidence:[ev],acceptanceTests:[test],confidence:'high-static',gaps:['Representative body observation only; full branch and runtime fixture validation remains.']});
}
