// Exhaustive declaration-to-capability crosswalk. Membership is not a behavioral parity claim.
function idsFor(t){
 const ns=t.namespace;
 if(ns==='CounterSketchServer.Commands')return ['CAD-046'];
 if(ns.startsWith('CS.CSValues'))return t.name==='CSScript'?['CAD-004']:ns.includes('CSValueHandle')?['CAD-005']:['CAD-003'];
 if(ns.startsWith('CSBlocks.Rails'))return ['CAD-006'];
 if(ns.startsWith('CSBlocks.Gems'))return ['CAD-007','CAD-008','CAD-009','CAD-010'];
 if(ns.startsWith('CSBlocks.GemClusters'))return t.legacy?['CAD-012']:['CAD-011'];
 if(ns.startsWith('CSBlocks.Settings.Heads.CSHeadBuilderV2'))return ['CAD-013'];
 if(ns.startsWith('CSBlocks.Settings.Heads'))return ['CAD-014'];
 if(ns.startsWith('CSBlocks.Settings.Bezels')||ns.startsWith('CSBlocks.Settings.Obsolete.Bezels'))return ['CAD-015'];
 if(ns.startsWith('CSBlocks.Settings.FrenchHalo'))return ['CAD-020'];
 if(ns.startsWith('CSBlocks.Settings'))return ['CAD-016'];
 if(ns.startsWith('CSBlocks.Shank.French'))return ['CAD-019'];
 if(ns.startsWith('CSBlocks.Shank.Matching')||ns.startsWith('CSBlocks.Shank.Obsolete'))return ['CAD-018'];
 if(ns.startsWith('CSBlocks.Shank'))return ['CAD-017'];
 if(ns.startsWith('CSBlocks.Linked'))return ['CAD-021'];
 if(ns.startsWith('CSBlocks.Builders'))return ['CAD-022'];
 if(ns.startsWith('CSBlocks.Cutters'))return ['CAD-023'];
 if(ns.startsWith('CSBlocks.Profiles'))return ['CAD-026'];
 if(ns.startsWith('CSBlocks.Caps')||ns.startsWith('CSBlocks.Collars'))return ['CAD-027'];
 if(ns.startsWith('CSBlocks.Bails'))return t.name==='CSVolumeCentroid'?['CAD-038']:['CAD-028'];
 if(ns.startsWith('CSBlocks.Curves'))return ['CAD-029','CAD-030','CAD-037'];
 if(ns.startsWith('CSBlocks.Sweeps'))return ['CAD-031'];
 if(ns.startsWith('CSBlocks.Surfaces'))return ['CAD-024','CAD-032','CAD-033','CAD-034'];
 if(ns.startsWith('CSBlocks.Solids'))return ['CAD-035'];
 if(ns.startsWith('CSBlocks.Transforms'))return t.name==='CSMilgrainPoints'?['CAD-025']:['CAD-036'];
 if(ns.startsWith('CSBlocks.UDT'))return t.name==='CSFlowAlongSurface'?['CAD-036']:['CAD-037'];
 if(ns.startsWith('CSBlocks.Tools'))return t.name==='CSTextObjects'?['CAD-039']:['CAD-037'];
 if(ns.startsWith('CSBlocks.SMI'))return ['CAD-041'];
 if(ns.startsWith('CSBlocks.Maths')||ns.startsWith('CSBlocks.Utilities'))return ['CAD-042'];
 if(ns.startsWith('CSBlocks.Core'))return ['CAD-037','CAD-040','CAD-043'];
 if(ns==='CSBlocks')return t.name==='CSNullBlock'?['CAD-002']:['CAD-001'];
 return ['CAD-001'];
}
